// Le vendredi soir, le brief porte sur le lundi : on corrige l'en-tete
// + en-tete de l'alerte camions : "Lundi lundi 12 octobre" -> "Lundi 12 octobre", "Demain lundi 12 octobre" -> "Demain, lundi 12 octobre"
const now = DateTime.now().setZone('Europe/Paris');
let matin = false;
try { matin = $('Chaque matin 8h15').isExecuted; } catch (e) {}
const nettoie = t => String(t || '')
  .replace(/<b>Lundi lundi /, '<b>Lundi ')
  .replace(/<b>Demain ([a-zé]+ \d)/, '<b>Demain, $1');
if (matin || now.weekday !== 5) return $input.all().map(i => ({ json: Object.assign({}, i.json, { text: nettoie(i.json.text) }) }));
const lundi = now.plus({ days: 3 }).setLocale('fr').toFormat('cccc d LLLL');
return $input.all().map(i => ({ json: Object.assign({}, i.json, {
  text: nettoie(String(i.json.text || '').replace(/<b>Demain, [^<]*<\/b>/, '<b>Lundi : ' + lundi + '</b>').replace('Rien de prévu demain.', 'Rien de prévu lundi.'))
}) }));

const src = $('Préparer prompt').all();
return $input.all().map((it, i) => {
  let t = '';
  try { t = (it.json.content || []).map(c => c.text || '').join('').trim(); } catch (e) {}
  t = t.replace(/\s+/g, ' ').replace(/[\u2013\u2014]/g, '-').slice(0, 200);
  const s = src[i].json;
  return { json: { ref: s.ref, devis_id: s.devisId, statut: t ? 'ok' : 'erreur', resume: t } };
});

const refs = $('Refs à résumer').all();
return $input.all().map((it, i) => {
  const ref = refs[i].json.ref;
  const r = it.json || {};
  const items = (r.ok && r.data && r.data.items) || [];
  const exact = items.filter(d => String(d.reference || '').toUpperCase() === ref);
  const d = exact.find(x => x.status === 'signed') || exact[0];
  return { json: { ref, devisId: d ? String(d.id) : '', statutDevis: d ? d.status : '' } };
});

const r = $('Lire planning').first().json;
if (!r.ok) throw new Error('Interfast events KO : ' + (r.erreur || r.statusCode));
const rdv = $input.first().json;
const items = (r.data.items || []).concat(rdv && rdv.ok && rdv.data ? (rdv.data.items || []) : []);
const JULIEN = 5198, AXEL = 9965, LAURENT = 5066;
const out = [];
const vus = new Set();
for (const ev of items) {
  if (vus.has(String(ev.id))) continue;
  vus.add(String(ev.id));
  const ids = ev.technicianIds || [];
  const pourLaurent = ids.includes(LAURENT);
  if (ev.category !== 'intervention' && ev.category !== 'meeting' && !pourLaurent) continue;
  if (ev.finished || ev.lifecycleState === 'cancelled') continue;
  const names = {};
  for (const u of (ev.users || [])) names[u.id] = u.firstName || u.lastName || ('tech ' + u.id);
  let techs = ids.slice();
  let exJulien = false;
  if (techs.includes(JULIEN)) {
    techs = techs.filter(t => t !== JULIEN);
    if (!techs.includes(AXEL)) { techs.push(AXEL); names[AXEL] = 'Axel'; exJulien = true; }
  }
  techs.sort((a, b) => a - b);
  const m = String(ev.address || '').match(/(\d{5})[\s,]+(.+)$/);
  out.push({ json: {
    vide: false, kind: ev.category || 'intervention', eventId: String(ev.id), interventionRef: ev.reference || '',
    start: ev.start, heure: ev.heureParis, code: ev.codeHoraire,
    sansHeure: ev.category === 'meeting' && !techs.includes(LAURENT),
    client: (ev.client && ev.client.name) || '',
    clientId: (ev.client && ev.client.id) ? String(ev.client.id) : '',
    ville: m ? m[2].trim() : (ev.address || '').trim(), adresse: ev.address || '',
    type: ev.type || '', titre: ev.title || '',
    ref: String(ev.secondReference || '').trim().toUpperCase(),
    sousContrat: !!ev.sousContrat, techs, techNames: names, exJulien
  } });
}
out.sort((a, b) => (a.json.sansHeure - b.json.sansHeure) || String(a.json.start).localeCompare(String(b.json.start)));
return out.length ? out : [{ json: { vide: true } }];

function lignes(items, out) {
  for (const x of (items || [])) {
    if (x.type === 'section') { lignes(x.items, out); continue; }
    if (x.isOption) continue;
    const nom = String(x.name || '').replace(/\s+/g, ' ').trim();
    if (!nom) continue;
    out.push('- ' + (x.quantity == null ? 1 : x.quantity) + ' ' + (x.unit || '') + ' : ' + nom.slice(0, 300));
  }
  return out;
}
return $input.all().map(it => {
  const r = it.json || {};
  const d = r.data || {};
  return { json: {
    ref: String(d.reference || '').toUpperCase(), devisId: String(d.id || ''),
    titre: d.name || '', ok: !!r.ok,
    lignes: r.ok ? lignes(d.items, []).join('\n').slice(0, 6000) : ''
  } };
});

const ok = new Set($input.all().map(i => i.json).filter(r => r && r.ref && r.statut === 'ok').map(r => String(r.ref).toUpperCase()));
const refs = new Set();
for (const it of $('Préparer interventions').all()) {
  const j = it.json;
  if (!j.vide && j.ref && !ok.has(j.ref)) refs.add(j.ref);
}
return [...refs].map(ref => ({ json: { ref } }));

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
function safeAll(n) { try { return $(n).all().map(i => i.json); } catch (e) { return []; } }
let matin = false; try { matin = $('Chaque matin 8h15').isExecuted; } catch (e) {}
const maintenant = DateTime.now().setZone('Europe/Paris');
const dimanche = maintenant.weekday === 7;
const vendredi = maintenant.weekday === 5;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
function coupe(s, n) { s = String(s || ''); if (s.length <= n) return s; const c = s.slice(0, n); const i = c.lastIndexOf(' '); return (i > n * 0.6 ? c.slice(0, i) : c) + '...'; }
function plat(x) { return String(x || '').replace(/\s*\n\s*/g, ', ').replace(/[,\s]+$/, '').trim(); }
const inter = $('Préparer interventions').all().map(i => i.json).filter(j => !j.vide);
const det = {}; for (const r of safeAll('Lire intervention')) if (r && r.ok && r.data) det[String(r.data.id)] = r.data;
const cli = {}; for (const r of safeAll('Lire client')) if (r && r.ok && r.data) cli[String(r.data.id)] = r.data;
const cache = {}; for (const r of safeAll('Lire cache brief')) if (r && r.ref) cache[String(r.ref).toUpperCase()] = r;
const memo = {}; for (const r of safeAll('Mémoire client')) if (r && r.eventId) memo[String(r.eventId)] = r;
const users = $input.all().map(i => i.json).filter(u => u.actif && u.telegram_id);
const jour = maintenant.plus({ days: matin ? 0 : (vendredi ? 3 : 1) }).setLocale('fr').toFormat('cccc d LLLL');
const LIB = { 1: 'approx.', 2: 'demi-journée', 3: 'journée entière' };
const LIBLONG = { 1: 'approx., battement 15-30 min', 2: 'demi-journée', 3: 'journée entière' };
function horaire(j, court) {
  if (j.sansHeure) return 'Dans la journée';
  const h = String(j.heure || '?').replace(':', 'h').replace(/^0/, '');
  const lib = (court ? LIB : LIBLONG)[j.code];
  return lib ? h + ' (' + lib + ')' : h;
}
function objet(j) {
  if (j.kind && j.kind !== 'intervention') return (j.kind === 'task' ? 'Tâche : ' : '') + (j.titre || j.type);
  const t = String(j.type || '').trim();
  const generique = !t || /^(intervention|dépannage|depannage|tâche|tache)( - climatpro)?$/i.test(t);
  if (generique) return j.titre || t;
  return t.replace(/^Entretien - Maintenance de PAC et climatisation$/i, 'Entretien');
}
function nomTech(j, t) { return j.techNames[t] || ('tech ' + t); }
function chantier(j) { return /install|pose/i.test((j.type || '') + ' ' + (j.titre || '')); }
function contactsDe(c) {
  const g = c.clientParticular || c.clientProfessional || c.clientOwnersAssociation || {};
  const l = (g.contacts || []).slice();
  if (g.contact) l.push(g.contact);
  return { g, l };
}
function ficheClient(j) {
  if ((j.kind && j.kind !== 'intervention') || !j.clientId) return null;
  return cli[j.clientId] || null;
}
function telManquant(j) {
  const c = ficheClient(j); if (!c) return false;
  const { g, l } = contactsDe(c);
  return !(l.some(x => x && (x.phoneNumber || x.secondaryPhoneNumber)) || g.phoneNumber || c.phoneNumber);
}
function emailManquant(j) {
  const c = ficheClient(j); if (!c) return false;
  const { g, l } = contactsDe(c);
  return !(l.some(x => x && String(x.email || '').includes('@')) || String(g.email || '').includes('@') || String(c.email || '').includes('@'));
}
function materiel(j) {
  if (j.kind && j.kind !== 'intervention') return null;
  if (!j.ref) {
    if (j.sousContrat) return 'entretien sous contrat';
    return chantier(j) ? 'ATTENTION aucun devis lié (référence externe vide)' : null;
  }
  const c = cache[j.ref];
  if (!c) return 'devis ' + j.ref + ' pas encore résumé';
  if (c.statut === 'ok') return c.resume + ' (' + j.ref + ')';
  if (c.statut === 'introuvable') return 'ATTENTION devis ' + j.ref + ' introuvable dans Interfast';
  return 'résumé indisponible (' + j.ref + ')';
}
function infos(j) {
  const L = [];
  const d = det[j.eventId];
  const a = d && d.address;
  if (a && a.address) {
    const extra = [a.additionalLine, a.comments].map(plat).filter(Boolean);
    L.push('Adresse : ' + a.address + ', ' + (a.zipCode || '') + ' ' + (a.city || '') + (extra.length ? ' - ' + extra.join(' - ') : ''));
  } else if (j.adresse) L.push('Adresse : ' + j.adresse);
  const c = j.clientId && cli[j.clientId];
  let nomContact = '';
  if (c) {
    const { l } = contactsDe(c);
    const aid = a && a.id;
    const ct = l.find(x => aid && x.phoneNumber && (x.addressIds || []).includes(aid)) || l.find(x => x.phoneNumber && (x.roles || []).includes('primary')) || l.find(x => x.phoneNumber);
    if (ct) {
      nomContact = [ct.firstName, ct.lastName].filter(Boolean).join(' ');
      L.push('Contact : ' + [nomContact, ct.phoneNumber, plat(ct.comment)].filter(Boolean).join(' - '));
    }
    const com = plat(c.commentary);
    if (com && norm(com) !== norm(j.client) && norm(com) !== norm(nomContact) && norm(com) !== norm(c.displayName)) L.push('Note fiche : ' + coupe(com, 300));
  }
  const desc = plat(d && d.description);
  if (desc) {
    const nd = norm(desc), nt = norm(j.titre);
    if (!(nt.length > 15 && nd.startsWith(nt.slice(0, 40)))) L.push('Note RDV : ' + coupe(desc, 300));
  }
  return L;
}
function lieu(j) { return [j.client, j.ville].filter(Boolean).join(', '); }
function blocTech(j, pour) {
  const L = ['<b>' + esc(horaire(j, false)) + '</b>' + (lieu(j) ? ' - ' + esc(lieu(j)) : '')];
  const o = j.titre && j.titre !== j.type ? j.type + ' : ' + j.titre : j.type;
  if (o) L.push(esc(o));
  const m = materiel(j);
  if (m) L.push('Matériel : ' + esc(m));
  for (const x of infos(j)) L.push(esc(x));
  const mm = memo[j.eventId];
  if (mm && mm.tech) L.push('<b>À retenir</b>\n' + esc(mm.tech));
  if (telManquant(j)) L.push('<b>ATTENTION : pas de téléphone client dans la fiche. Préviens Laurent ce soir.</b>');
  if (emailManquant(j)) L.push('A faire sur place : demander l email du client (non renseigné dans la fiche).');
  const noms = j.techs.filter(t => t !== pour).map(t => nomTech(j, t));
  if (noms.length) L.push('Avec : ' + esc(noms.join(', ')));
  if (j.exJulien) L.push('(planifié au nom de Julien, attribué à Axel : à confirmer)');
  return L.join('\n');
}
function finir(L) {
  let t = L.join('\n');
  if (t.length > 4000) t = t.slice(0, 3900).replace(/<[^>]*$/, '') + '\n... (suite tronquée)';
  return t;
}
function aCaler(liste, L) {
  const caler = liste.filter(j => j.code === 4);
  if (!caler.length) return;
  L.push('', '<b>À caler (date non fixée)</b>');
  for (const j of caler) L.push('- ' + esc(lieu(j) || objet(j)) + (j.ref ? ' (' + esc(j.ref) + ')' : ''));
}
function recapMatin(liste) {
  const prevus = liste.filter(j => j.code !== 4);
  const L = ['<b>Planning du ' + esc(jour) + '</b>'];
  if (!prevus.length) { L.push('Rien de prévu aujourd hui.'); aCaler(liste, L); return finir(L); }
  const parTech = {}, noms = {};
  for (const j of prevus) {
    const ts = j.techs.length ? j.techs.map(String) : ['?'];
    for (const t of ts) { (parTech[t] = parTech[t] || []).push(j); noms[t] = t === '?' ? 'Non attribué' : nomTech(j, t); }
  }
  const equipes = {};
  for (const t of Object.keys(parTech)) {
    const cle = parTech[t].map(j => j.eventId).join('|');
    (equipes[cle] = equipes[cle] || { techs: [], rdv: parTech[t] }).techs.push(t);
  }
  const rang = t => t === '5066' ? -1 : (t === '?' ? 1e12 : Number(t));
  const blocs = Object.values(equipes).sort((a, b) => rang(a.techs[0]) - rang(b.techs[0]));
  for (const e of blocs) {
    L.push('', '<b>' + esc(e.techs.map(t => noms[t]).join(' + ')) + '</b>');
    for (const j of e.rdv) {
      const autres = j.techs.map(String).filter(t => !e.techs.includes(t)).map(t => nomTech(j, t));
      let l = esc(horaire(j, true)) + ' - ' + [lieu(j), coupe(objet(j), 70)].filter(Boolean).map(esc).join(' - ');
      if (autres.length) l += ' (avec ' + esc(autres.join(', ')) + ')';
      if (j.exJulien) l += ' (planifié Julien)';
      if (telManquant(j)) l += ' <b>[tél manquant]</b>';
      L.push(l);
    }
  }
  aCaler(liste, L);
  return finir(L);
}
function briefSoir(liste, pour) {
  const prevus = liste.filter(j => j.code !== 4);
  const L = ['<b>Demain, ' + esc(jour) + '</b>'];
  if (!prevus.length) L.push('Rien de prévu demain.');
  for (const j of prevus) L.push('', blocTech(j, pour));
  aCaler(liste, L);
  return finir(L);
}
function memoAdmin(liste) {
  const avec = liste.filter(j => j.code !== 4 && memo[j.eventId] && (memo[j.eventId].admin || memo[j.eventId].tech));
  if (!avec.length) return null;
  const L = ['<b>Mémo clients du ' + esc(jour) + '</b>'];
  for (const j of avec) {
    const mm = memo[j.eventId];
    const qui = j.techs.map(t => nomTech(j, t)).join(', ');
    L.push('', '<b>' + esc(horaire(j, true)) + ' - ' + esc(lieu(j)) + '</b>' + (qui ? ' (' + esc(qui) + ')' : ''));
    L.push(esc(mm.admin || mm.tech));
  }
  return finir(L);
}
// Alerte camions pour Laurent : Christophe et Axel ensemble (un camion) ou séparés (deux camions)
function alerteCamions(liste) {
  const CH = 5069, AX = 9965;
  const quand = vendredi || dimanche ? 'Lundi ' + esc(jour) : 'Demain ' + esc(jour);
  const prevus = liste.filter(j => j.code !== 4 && j.kind !== 'task');
  const deC = prevus.filter(j => j.techs.includes(CH));
  const deA = prevus.filter(j => j.techs.includes(AX));
  const ligne = (j, qui) => (qui ? qui + ' ' : '') + esc(horaire(j, true)) + ' - ' + esc(coupe(lieu(j) || objet(j), 60));
  if (!deC.length && !deA.length) return '<b>' + quand + ' : aucune intervention prévue pour Christophe et Axel.</b>';
  if (!deA.length) return '<b>' + quand + ' : Christophe seul sur le terrain, Axel sans intervention. Un camion.</b>\n' + deC.map(j => ligne(j, '')).join('\n');
  if (!deC.length) return '<b>' + quand + ' : Axel seul sur le terrain, Christophe sans intervention. Un camion.</b>\n' + deA.map(j => ligne(j, '')).join('\n');
  const seulsC = deC.filter(j => !j.techs.includes(AX));
  const seulsA = deA.filter(j => !j.techs.includes(CH));
  const ensemble = deC.filter(j => j.techs.includes(AX));
  if (!seulsC.length && !seulsA.length) return '<b>' + quand + ' : Christophe et Axel ensemble toute la journée. Un seul camion.</b>\n' + ensemble.map(j => ligne(j, '')).join('\n');
  const L = ['<b>' + quand + ' : Christophe et Axel SÉPARÉS. Deux camions nécessaires.</b>'];
  if (ensemble.length) L.push('Ensemble : ' + ensemble.map(j => esc(horaire(j, true)) + ' ' + esc(coupe(lieu(j), 40))).join(' ; '));
  for (const j of seulsC) L.push(ligne(j, 'Christophe'));
  for (const j of seulsA) L.push(ligne(j, 'Axel'));
  return finir(L);
}
const out = [];
for (const u of users) {
  const admin = u.role === 'admin';
  const id = Number(u.interfast_id);
  if (matin && admin) out.push({ json: { chat_id: String(u.telegram_id), nom: u.nom, text: recapMatin(inter) } });
  if (!matin && admin) {
    out.push({ json: { chat_id: String(u.telegram_id), nom: u.nom, text: alerteCamions(inter) } });
    const m = memoAdmin(inter);
    if (m) out.push({ json: { chat_id: String(u.telegram_id), nom: u.nom, text: m } });
  }
  if (!matin && !admin && !dimanche && u.brief_18h) out.push({ json: { chat_id: String(u.telegram_id), nom: u.nom, text: briefSoir(inter.filter(j => j.techs.includes(id) || (id === 9965 && j.techs.includes(5198))), id) } });
}
return out;
